export function createState(){return{runId:null,fictionalTime:'19:03',minutes:0,ended:false,player:{x:145,y:430},tabitha:{x:190,y:414,target:{x:455,y:372},mood:'noticed something',speech:'Hang on.',speechUntil:3.5},activity:{stage:'approach_banner',tabithaInitiated:true,playerEngaged:false,bannerAttempt:null,sideSuggested:false,sideReached:false,focusedExchangeSeen:false,resolved:false,pendingEnding:null},banner:{heldByPlayer:false,torchUsed:false,touchedByTabitha:false,warnedOff:false,visibleText:'',dateVisible:false},facts:{lettersSeen:null,dateSeen:null,doorConfirmed:false,playerFoundHinge:false,hingeFoundBy:null,playerChallengedDoor:false,seamInspected:false,plaqueSeen:false,roomName:null,tabithaLibraryMentioned:false},dynamic:{workingStyle:'unknown',playerCredit:0,tabithaLead:0,cautious:false,teasing:false},conduct:[],trace:[],visibleChanges:[],ending:null};}
export function record(s,type,payload={}){s.trace.push({index:s.trace.length,type,fictionalTime:s.fictionalTime,...payload});}
export function visible(s,kind,detail){const x={index:s.visibleChanges.length,kind,detail};s.visibleChanges.push(x);record(s,'visible_change',x);return x;}
export function advanceFiction(s,minutes,reason){if(s.ended)return;s.minutes+=minutes;const total=19*60+3+s.minutes;s.fictionalTime=`${String(Math.floor(total/60)).padStart(2,'0')}:${String(total%60).padStart(2,'0')}`;record(s,'fiction_advanced',{minutes,reason});}
export function tabithaReachedBanner(s){if(s.activity.stage!=='approach_banner')return;s.activity.stage='banner';s.tabitha.mood='examining banner';s.tabitha.speech="They've put it over the old name.";s.tabitha.speechUntil+=4;visible(s,'initiative','Tabitha walks over and starts inspecting the banner without waiting for you.');record(s,'tabitha_initiative',{action:'inspect_banner'});}
export function bannerAction(s,a){if(s.ended||!['banner','banner_clue'].includes(s.activity.stage))return;s.activity.playerEngaged=true;s.activity.bannerAttempt??=a;s.conduct.push(a);record(s,'banner_action',{action:a});if(a==='hold_corner'){s.banner.heldByPlayer=true;s.banner.touchedByTabitha=true;s.banner.visibleText='...STITUTE';s.facts.lettersSeen='STITUTE';s.dynamic.workingStyle='cooperative';s.dynamic.tabithaLead++;visible(s,'physical','You hold the loose vinyl while Tabitha leans in to read the stone behind it.');s.tabitha.speech='Hold it there—yeah. I can see ...STITUTE.';}else if(a==='phone_torch'){s.banner.torchUsed=true;s.banner.touchedByTabitha=true;s.banner.visibleText='...INSTITUTE';s.facts.lettersSeen='INSTITUTE';s.dynamic.workingStyle='cooperative';visible(s,'physical','Tabitha holds the corner while you angle your phone torch behind the banner.');s.tabitha.speech='Left. Left. There. INSTITUTE.';}else if(a==='let_tabitha_try'){s.banner.touchedByTabitha=true;s.banner.visibleText='...TUTE';s.facts.lettersSeen='TUTE';s.dynamic.workingStyle='tabitha_leads';s.dynamic.tabithaLead+=2;visible(s,'physical','You leave it to Tabitha. She gets one corner up with two fingers and immediately regrets the leverage.');s.tabitha.speech='TUTE. Brilliant. A historically significant syllable.';}else if(a==='warn_off'){s.banner.warnedOff=true;s.dynamic.workingStyle='cautious';s.dynamic.cautious=true;visible(s,'boundary','You tell Tabitha not to start peeling council property off the wall. She lets the vinyl drop.');s.tabitha.speech='Fine. No peeling. We can still look at the masonry.';suggestSide(s,'caution');return;}s.tabitha.speechUntil+=3;s.activity.stage='banner_clue';advanceFiction(s,3,`banner:${a}`);}
export function inspectBannerClue(s,a){if(s.ended||s.activity.stage!=='banner_clue')return;s.conduct.push(a);record(s,'banner_clue_action',{action:a});if(a==='read_letters'){const t=s.banner.visibleText||'...TUTE';s.facts.lettersSeen=t.replace(/\.+/g,'');s.tabitha.speech=s.facts.lettersSeen.includes('INSTITUTE')?'Institute. That makes the side entrance theory annoyingly plausible.':'Something ending in TUTE. Institute is my current least stupid guess.';visible(s,'discovery',`The exposed letters read ${t}.`);}else if(a==='check_date'){s.banner.dateVisible=true;s.facts.dateSeen='1908';s.tabitha.speech='1908. Old enough for a side reading-room entrance.';visible(s,'discovery','Below the vinyl, a carved date reads 1908.');}else if(a==='challenge_institute'){s.facts.playerChallengedDoor=true;s.tabitha.speech='Could be something else. Side wall will tell us more than guessing here.';visible(s,'conversation','You challenge Tabitha’s guess instead of accepting it.');}s.tabitha.speechUntil+=3;advanceFiction(s,2,`banner_clue:${a}`);suggestSide(s,a);}
export function suggestSide(s,reason){if(s.activity.sideSuggested)return;s.activity.sideSuggested=true;s.activity.stage='moving_side';s.tabitha.target={x:716,y:258};s.tabitha.mood='checking side wall';s.tabitha.speech=s.dynamic.cautious?'Round the side. Looking at bricks remains legal, I think.':'If there was an institute entrance, it should be round the side. Come on.';s.tabitha.speechUntil+=4;visible(s,'initiative','Tabitha decides the front has given enough clues and heads round the side of the hall.');record(s,'tabitha_initiative',{action:'move_side',reason});}
export function tabithaReachedSide(s){if(s.activity.stage!=='moving_side')return;s.activity.stage='side';s.activity.sideReached=true;s.tabitha.mood='reading brickwork';s.tabitha.speech='There. Straight joint in the bricks.';s.tabitha.speechUntil+=4;visible(s,'initiative','Tabitha stops at a vertical seam in the side wall and points it out.');}
export function sideAction(s,a){if(s.ended||!['side','side_search'].includes(s.activity.stage))return;s.conduct.push(a);record(s,'side_action',{action:a});if(a==='inspect_seam'){s.activity.stage='side_search';s.facts.seamInspected=true;visible(s,'physical','You trace the straight mortar joint where the brick pattern changes.');s.tabitha.speech='Exactly. Opening was about this wide.';}else if(a==='check_rust'){findHinge(s,'player');}else if(a==='ask_what_she_sees'){s.activity.stage='side_search';visible(s,'conversation','You ask Tabitha to show you what she is reading in the wall.');}else if(a==='call_it_repair'){s.facts.playerChallengedDoor=true;s.activity.stage='side_search';s.tabitha.speech='Could be. Check me instead of agreeing.';visible(s,'conversation','You tell her it could just be a repair.');}s.tabitha.speechUntil+=3;advanceFiction(s,2,`side:${a}`);}
export function applyDialogueEffect(s,e){if(!e)return;record(s,'dialogue_effect',{effect:e});if(e==='find_hinge')findHinge(s,'player');else if(e==='confirm_door')confirmDoor(s,'player');else if(e==='tabitha_confirms')confirmDoor(s,'tabitha');else if(e==='player_takes_credit'){s.dynamic.playerCredit++;s.dynamic.teasing=true;}else if(e==='working_pair_tease'){s.dynamic.teasing=true;s.dynamic.workingStyle='bantering_pair';}else if(e==='tabitha_leads_hinge_search'){s.dynamic.tabithaLead++;s.activity.stage='side_search';}else if(e==='door_confirmed')confirmDoor(s,'shared');else if(e==='tabitha_shared_skill'){s.facts.tabithaLibraryMentioned=true;s.activity.stage='side_search';}}
export function findHinge(s,by){if(s.facts.playerFoundHinge&&by==='player')return;s.facts.playerFoundHinge=by==='player'||s.facts.playerFoundHinge;s.facts.hingeFoundBy??=by;s.activity.stage='side_search';if(by==='player')s.dynamic.playerCredit++;visible(s,'discovery',`${by==='player'?'You find':'Tabitha finds'} a rust rectangle and two old screw holes beside the seam.`);}
export function confirmDoor(s,by){if(!s.facts.doorConfirmed){s.facts.doorConfirmed=true;visible(s,'discovery','The brick bond and hinge marks line up: this really was a doorway.');}s.activity.stage='door_confirmed';s.tabitha.target={x:735,y:178};s.tabitha.mood='looking for plaque';s.tabitha.speech=by==='player'?'Okay. You have that one. There should be a room plaque higher up.':'Door confirmed. Plaque next, if they left us anything.';s.tabitha.speechUntil+=4;record(s,'tabitha_initiative',{action:'search_plaque',after:by});}
export function inspectPlaque(s){if(s.ended||s.activity.stage!=='door_confirmed')return;s.facts.plaqueSeen=true;s.facts.roomName='READING ROOM';s.activity.stage='resolution';visible(s,'discovery','Under flaking paint, the surviving plaque reads READING ROOM.');s.tabitha.speech=finalCallback(s);s.tabitha.speechUntil+=6;advanceFiction(s,3,'plaque discovery');}
export function finalCallback(s){if(s.dynamic.cautious)return'Reading Room. See? Entire investigation, zero council vinyl harmed.';if(s.dynamic.playerCredit>=1&&s.dynamic.tabithaLead>=1)return'Reading Room. You got the hinge; I got the doorway. I can live with that division of labour.';if(s.dynamic.teasing)return'Reading Room. We are both unbearable now; that seems fair.';if(s.dynamic.workingStyle==='tabitha_leads')return'Reading Room. Thank you for your vital contribution of letting me make all the bad decisions.';return'Reading Room. That was more satisfying than going inside immediately.';}
export function beginEnding(s,ending){if(s.ended||s.activity.pendingEnding)return;s.activity.pendingEnding=ending;if(ending==='keep_looking'){s.tabitha.target={x:770,y:408};s.tabitha.speech='Back wall next. If there is a boiler-room plaque, I want it.';}else if(ending==='inside_together'){s.tabitha.target={x:320,y:372};s.tabitha.speech='All right. We should probably go inside before Maya reports us missing.';}s.tabitha.speechUntil+=5;visible(s,'continuation',ending==='keep_looking'?'Tabitha heads toward the back wall with you.':'Tabitha turns back toward the entrance with you.');record(s,'ending_started',{ending});}
export function finishRun(s,ending){if(s.ended)return;s.ended=true;s.ending=ending;s.activity.pendingEnding=null;s.activity.resolved=true;record(s,'run_ended',{ending,facts:{...s.facts},dynamic:{...s.dynamic}});}
export function outcomeSummary(s){const lines=[];if(s.facts.roomName)lines.push(`You and Tabitha uncovered the old ${s.facts.roomName.toLowerCase()} entrance.`);else if(s.facts.doorConfirmed)lines.push('You and Tabitha confirmed that the side wall once held a doorway.');else if(s.facts.lettersSeen||s.facts.dateSeen)lines.push('You found part of the hall’s older identity beneath the new banner.');else lines.push('You chose not to pursue Tabitha’s curiosity very far.');if(s.ending==='inside_together')lines.push('You went inside together afterwards.');if(s.ending==='keep_looking')lines.push('You kept circling the building together.');if(s.ending==='leave')lines.push('You left instead of continuing the investigation.');return lines;}
